"use client";

import { Toaster as Sonner, type ToasterProps } from "sonner";
import { cn } from "@/lib/utils";
import "./liquid.css";

export { toast } from "sonner";

/** Sonner owns announcements, timers, stacking and swipe dismissal. */
export function Toaster({ className, toastOptions, ...props }: ToasterProps) {
  return (
    <Sonner
      position="top-center"
      offset={{ top: "max(20px, env(safe-area-inset-top))" }}
      mobileOffset={{ top: "max(16px, env(safe-area-inset-top))", left: 16, right: 16 }}
      visibleToasts={3}
      closeButton
      className={cn("liquid-toaster", className)}
      {...props}
      toastOptions={{
        ...toastOptions,
        classNames: {
          ...toastOptions?.classNames,
          toast: cn("liquid-surface liquid-toast", toastOptions?.classNames?.toast),
        },
      }}
    />
  );
}

/* Material defaults live on the root, so a value set on any ancestor reaches its glass. */
:root {
  --liquid-blur: 20px;
  --liquid-tint: 0.22;
  --liquid-ink: #172323;
  --liquid-fill: 255 255 255;
}
.liquid-surface {
  position: relative;
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / var(--liquid-tint));
  border: 1px solid rgb(255 255 255 / 0.65);
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  box-shadow:
    inset 0 1px 1px rgb(255 255 255 / 0.9),
    inset 0 -1px 1px rgb(255 255 255 / 0.25),
    inset 2px 0 5px rgb(255 255 255 / 0.18),
    0 8px 28px rgb(0 20 25 / 0.14);
  transition:
    background 200ms ease,
    box-shadow 200ms ease;
}
.liquid-surface:focus-visible,
.liquid-tab:focus-visible,
.liquid-toolbar-button:focus-visible {
  outline: 3px solid #007aff;
  outline-offset: 4px;
}
.liquid-interactive {
  position: relative;
  isolation: isolate;
  translate: var(--liquid-x, 0px) var(--liquid-y, 0px);
  scale: var(--liquid-scale-x, 1) var(--liquid-scale-y, 1);
  /* The spring owns translate/scale; consumers still own transform. */
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    opacity 140ms ease;
}
/* Pointer light. Pressing floods the glass with light as it swells toward the finger. */
.liquid-interactive::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(
    ellipse at var(--liquid-light-x, 50%) var(--liquid-light-y, 25%),
    rgb(255 255 255 / calc(0.48 + 0.32 * var(--liquid-press, 0))),
    rgb(255 255 255 / calc(0.07 + 0.2 * var(--liquid-press, 0))) 45%,
    transparent 72%
  );
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / calc(0.28 + 0.42 * var(--liquid-press, 0))),
    inset 0 0 calc(16px * var(--liquid-press, 0))
      rgb(255 255 255 / calc(0.5 * var(--liquid-press, 0)));
  opacity: var(--liquid-light, 0);
  z-index: -1;
}
/* Content morph: new content condenses out of light while the width springs. */
.liquid-interactive[data-liquid-morphing] {
  overflow: clip;
}
.liquid-interactive[data-liquid-morph="a"] {
  animation: liquid-ink-in-a 420ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.liquid-interactive[data-liquid-morph="b"] {
  animation: liquid-ink-in-b 420ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.liquid-interactive[data-liquid-morph="a"] > svg {
  animation: liquid-glyph-in-a 480ms cubic-bezier(0.2, 0.9, 0.25, 1.25);
}
.liquid-interactive[data-liquid-morph="b"] > svg {
  animation: liquid-glyph-in-b 480ms cubic-bezier(0.2, 0.9, 0.25, 1.25);
}
@keyframes liquid-ink-in-a {
  from {
    color: transparent;
    text-shadow: 0 0 12px rgb(255 255 255 / 0.95);
  }
}
@keyframes liquid-ink-in-b {
  from {
    color: transparent;
    text-shadow: 0 0 12px rgb(255 255 255 / 0.95);
  }
}
@keyframes liquid-glyph-in-a {
  from {
    opacity: 0;
    filter: blur(5px);
    scale: 0.45;
  }
}
@keyframes liquid-glyph-in-b {
  from {
    opacity: 0;
    filter: blur(5px);
    scale: 0.45;
  }
}
.liquid-button {
  border-radius: 999px;
  min-height: 44px;
  font-weight: 600;
  padding-inline: 24px;
}
.liquid-button:hover:not(:disabled) {
  background: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + 0.1));
  box-shadow:
    inset 0 1px 2px white,
    inset 0 -1px 2px rgb(190 224 255 / 0.5),
    0 12px 32px rgb(0 20 25 / 0.2);
}
.liquid-button[data-size^="icon"] {
  padding-inline: 0;
  min-width: 44px;
}
.liquid-button[data-liquid-variant="destructive"] {
  --liquid-ink: #a20c22;
  --liquid-fill: 255 200 208;
}
.liquid-button[data-liquid-variant="link"] {
  text-decoration: underline;
}
.liquid-button[data-liquid-variant="secondary"] {
  background: rgb(var(--liquid-fill) / 0.55);
}
.liquid-button[data-state="open"] > svg {
  rotate: 180deg;
}
.liquid-button > svg {
  transition: rotate 350ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* Segmented tabs and toolbars share one lens. */
.liquid-tabs {
  border-radius: 999px;
  padding: 5px;
  height: 52px;
  gap: 3px;
  isolation: isolate;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    scale 460ms cubic-bezier(0.25, 1.45, 0.45, 1);
}
.liquid-tabs[data-orientation="vertical"] {
  height: auto;
  border-radius: 26px;
  touch-action: pan-x;
}
/* The whole bar swells a little while a finger is on it. */
.liquid-tabs[data-liquid-pressed] {
  scale: 1.025;
  transition-duration: 200ms, 200ms, 240ms;
}
.liquid-tab {
  position: relative;
  color: var(--liquid-ink);
  border-radius: 999px;
  padding-inline: 22px;
  height: 40px;
  background: transparent;
  transition: color 180ms ease;
}
.liquid-tab[data-state="active"] {
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / 0.58);
  box-shadow:
    0 2px 8px rgb(0 0 0 / 0.12),
    inset 0 1px 1px rgb(255 255 255 / 0.8);
}
.liquid-tabs[data-liquid-indicator] .liquid-tab[data-state="active"] {
  background: transparent;
  box-shadow: none;
}
.liquid-tab:hover:not(:disabled) {
  color: var(--liquid-ink);
}
/* An iOS tab bar: add `liquid-tabbar` to a TabsList to stack icons over labels. */
.liquid-tabbar {
  height: 66px;
  padding: 5px;
  gap: 0;
}
.liquid-tabbar .liquid-tab {
  height: 54px;
  min-width: 88px;
  flex-direction: column;
  gap: 3px;
  padding-inline: 14px;
  font-size: 11px;
  font-weight: 600;
}
.liquid-tabbar .liquid-tab svg {
  width: 23px;
  height: 23px;
}
.liquid-lens {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  overflow: hidden;
  border-radius: 999px;
  pointer-events: none;
  /* At rest: a frosted pill. Lifted: clear glass with a bright, faintly chromatic rim. */
  background:
    linear-gradient(
      135deg,
      rgb(255 255 255 / calc(0.2 * (1 - var(--liquid-lift, 0)))),
      transparent 55%
    ),
    rgb(
      var(--liquid-lens-fill, 255 255 255) /
        calc(var(--liquid-lens-alpha, 0.5) * (1 - 0.8 * var(--liquid-lift, 0)))
    );
  box-shadow:
    inset 0 1px 1.5px rgb(255 255 255 / calc(0.75 + 0.25 * var(--liquid-lift, 0))),
    inset 0 -1px 1.5px rgb(255 255 255 / calc(0.25 + 0.5 * var(--liquid-lift, 0))),
    inset 2px 0 3px -1px rgb(255 110 190 / calc(0.55 * var(--liquid-lift, 0))),
    inset -2px 0 3px -1px rgb(70 200 255 / calc(0.55 * var(--liquid-lift, 0))),
    0 calc(2px + 8px * var(--liquid-lift, 0)) calc(8px + 22px * var(--liquid-lift, 0))
      rgb(0 20 25 / calc(0.1 + 0.12 * var(--liquid-lift, 0)));
  opacity: 0;
  transition: opacity 200ms ease;
}
[data-liquid-indicator] > .liquid-lens {
  opacity: 1;
}
/* An inert copy of the list, magnified and tinted inside the lens. */
.liquid-lens > .liquid-lens-optics {
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  color: var(--liquid-lens-ink, var(--liquid-accent, var(--liquid-system-accent, #007aff)));
  /* The copy carries the list's classes; strip its material, whichever rule set it. */
  background: none !important;
  border-color: transparent !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  text-shadow: none;
  translate: none;
  scale: none;
  transition: none;
  animation: none;
  pointer-events: none;
}
.liquid-lens-optics * {
  color: inherit !important;
  text-shadow: none !important;
  transition: none !important;
  animation: none !important;
}
.liquid-lens-optics > * {
  background: transparent !important;
  box-shadow: none !important;
  border-color: transparent !important;
  translate: none !important;
  scale: none !important;
}
.liquid-lens-optics *::before {
  opacity: 0 !important;
}
/* Once the lens has landed the copy stands in for the selected label. */
[data-liquid-lens="rest"]
  :is(.liquid-tab[data-state="active"], .liquid-toolbar-button[aria-pressed="true"]):not(
    .liquid-lens *
  ) {
  color: transparent;
  text-shadow: none;
}
.liquid-menu {
  --liquid-menu-x: 0px;
  --liquid-menu-y: -10px;
  --liquid-menu-scale-x: 0.8;
  --liquid-menu-scale-y: 0.6;
  --liquid-menu-radius: 70px;
  --liquid-menu-mid-x: 0px;
  --liquid-menu-mid-y: -5px;
  --liquid-menu-mid-scale-x: 0.7;
  --liquid-menu-mid-scale-y: 0.7;
  border-radius: 22px;
  padding: 6px;
  min-width: 220px;
  background: rgb(var(--liquid-fill) / max(var(--liquid-tint), 0.68));
  transform-origin: center;
  transition: background 200ms ease;
}
.liquid-menu [role^="menuitem"] {
  min-height: 40px;
  border-radius: 15px;
  color: inherit;
  transition: background 140ms ease;
}
.liquid-menu [role^="menuitem"][data-highlighted] {
  background: rgb(0 122 255 / 0.16);
}
.liquid-menu [data-variant="destructive"] {
  color: #c52238;
}
.liquid-menu-body {
  transform-origin: 50% 40%;
}
.liquid-menu[data-state="open"]:not([data-liquid-morph="ready"]) {
  opacity: 0;
}
.liquid-menu[data-state="open"][data-liquid-morph="ready"] {
  animation: liquid-menu-unfold var(--liquid-morph-duration, 520ms) both;
}
.liquid-menu[data-state="open"][data-liquid-morph="ready"] > .liquid-menu-body {
  animation: liquid-menu-body-in var(--liquid-morph-duration, 520ms) both;
}
.liquid-menu[data-state="closed"] {
  animation: liquid-menu-fold 320ms both;
  pointer-events: none;
}
.liquid-menu[data-state="closed"] > .liquid-menu-body {
  animation: liquid-menu-body-out 130ms ease-in both;
}
/* The trigger swells into a round droplet, which stretches into the panel. */
@keyframes liquid-menu-unfold {
  0% {
    opacity: 0.7;
    transform: translate(var(--liquid-menu-x), var(--liquid-menu-y))
      scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y));
    border-radius: var(--liquid-menu-radius);
    animation-timing-function: cubic-bezier(0.3, 0.1, 0.5, 1);
  }
  26% {
    opacity: 1;
    transform: translate(var(--liquid-menu-mid-x), var(--liquid-menu-mid-y))
      scale(var(--liquid-menu-mid-scale-x), var(--liquid-menu-mid-scale-y));
    border-radius: 50%;
    animation-timing-function: cubic-bezier(0.2, 0.7, 0.3, 1);
  }
  62% {
    opacity: 1;
    transform: translate(0, 0) scale(1.025, 1.04);
    border-radius: 22px;
    animation-timing-function: cubic-bezier(0.3, 0, 0.3, 1);
  }
  100% {
    opacity: 1;
    transform: translate(0, 0) scale(1);
    border-radius: 22px;
  }
}
/* Content arrives magnified and out of focus, as if seen through the forming lens. */
@keyframes liquid-menu-body-in {
  0%,
  16% {
    opacity: 0;
    transform: scale(1.3);
    filter: blur(10px);
    animation-timing-function: cubic-bezier(0.2, 0.7, 0.3, 1);
  }
  55% {
    opacity: 1;
    transform: scale(1.05);
    filter: blur(1.5px);
  }
  100% {
    opacity: 1;
    transform: none;
    filter: none;
  }
}
@keyframes liquid-menu-body-out {
  to {
    opacity: 0;
    transform: scale(0.94);
    filter: blur(6px);
  }
}
/* The panel collapses into a droplet that is drawn back into its trigger. */
@keyframes liquid-menu-fold {
  0% {
    opacity: 1;
    transform: translate(0, 0) scale(1);
    border-radius: 22px;
    animation-timing-function: cubic-bezier(0.5, 0, 0.7, 0.4);
  }
  45% {
    opacity: 1;
    transform: translate(var(--liquid-menu-mid-x), var(--liquid-menu-mid-y))
      scale(
        calc(var(--liquid-menu-mid-scale-x) * 0.78),
        calc(var(--liquid-menu-mid-scale-y) * 0.95)
      );
    border-radius: 50%;
    animation-timing-function: cubic-bezier(0.3, 0, 0.2, 1);
  }
  100% {
    opacity: 0;
    transform: translate(var(--liquid-menu-x), var(--liquid-menu-y))
      scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y));
    border-radius: var(--liquid-menu-radius);
  }
}
/* A trigger covered by its menu becomes the menu, then reappears as the droplet lands. */
[data-liquid-covered] {
  transition: opacity 140ms ease 120ms;
}
[data-liquid-covered][data-state="open"] {
  opacity: 0;
  transition: opacity 90ms ease;
}
.liquid-toolbar {
  display: flex;
  align-items: center;
  padding: 6px;
  border-radius: 999px;
  gap: 4px;
  isolation: isolate;
}
.liquid-toolbar[data-orientation="vertical"] {
  flex-direction: column;
}
.liquid-toolbar-button {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
}
.liquid-toolbar-button svg {
  width: 21px;
  height: 21px;
}
.liquid-toolbar-button:hover:not(:disabled),
.liquid-toolbar-button[aria-pressed="true"] {
  background: rgb(255 255 255 / 0.18);
}
.liquid-toolbar[data-liquid-indicator] .liquid-toolbar-button[aria-pressed="true"] {
  background: transparent;
}
.liquid-toolbar-button:disabled {
  opacity: 0.5;
}
.liquid-toolbar-separator {
  height: 20px;
  width: 1px;
  background: rgb(255 255 255 / 0.4);
  margin-inline: 3px;
}
.liquid-toolbar-separator[data-orientation="horizontal"] {
  height: 1px;
  width: 20px;
  margin: 3px 0;
}
/* Dark lenses brighten the default accent for legible labels; --liquid-accent still wins. */
.dark .liquid-surface,
[data-liquid-theme="dark"] .liquid-surface {
  --liquid-fill: 22 27 30;
  --liquid-ink: #fff;
  --liquid-lens-alpha: 0.16;
  --liquid-system-accent: #5aabff;
  border-color: rgb(255 255 255 / 0.3);
}
[data-reduced-transparency="true"] .liquid-surface {
  background: rgb(var(--liquid-fill));
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
[data-reduced-transparency="true"] .liquid-lens {
  --liquid-lens-fill: 120 120 128;
  --liquid-lens-alpha: 0.16;
}
@supports not (backdrop-filter: blur(1px)) {
  .liquid-surface {
    background: rgb(var(--liquid-fill) / 0.96);
  }
}
@media (prefers-reduced-transparency: reduce), (prefers-contrast: more) {
  .liquid-surface {
    background: rgb(var(--liquid-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
  .liquid-lens {
    --liquid-lens-fill: 120 120 128;
    --liquid-lens-alpha: 0.16;
  }
}
/* No glass until hovered or pressed, in every material. After the material overrides. */
.liquid-button:is([data-liquid-variant="ghost"], [data-liquid-variant="link"]) {
  border-color: transparent;
  box-shadow: none;
  background: transparent;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
/* Tinted glass, like iOS .glassProminent. Placed after the material overrides it replaces. */
.liquid-button[data-liquid-variant="prominent"],
.liquid-button[data-liquid-variant="prominent"]:hover:not(:disabled) {
  --liquid-ink: #fff;
  color: #fff;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.22), transparent 60%), var(--liquid-accent, #007aff);
  border-color: rgb(255 255 255 / 0.35);
  box-shadow:
    inset 0 1px 1px rgb(255 255 255 / 0.55),
    inset 0 -1px 2px rgb(0 0 0 / 0.12),
    0 8px 24px color-mix(in srgb, var(--liquid-accent, #007aff) 35%, transparent);
}
[data-reduced-motion="true"] .liquid-surface,
[data-reduced-motion="true"] .liquid-interactive,
[data-reduced-motion="true"] .liquid-interactive > svg,
[data-reduced-motion="true"] .liquid-menu > *,
[data-reduced-motion="true"] .liquid-button > svg,
[data-reduced-motion="true"] .liquid-lens,
[data-reduced-motion="true"] [data-liquid-covered] {
  transition: none !important;
  animation: none !important;
}
[data-reduced-motion="true"] .liquid-interactive {
  translate: none;
  scale: none;
}
[data-reduced-motion="true"] .liquid-tabs {
  scale: none;
}
[data-reduced-motion="true"] .liquid-menu[data-state="open"] {
  opacity: 1;
}
@media (prefers-reduced-motion: reduce) {
  .liquid-surface,
  .liquid-tab,
  .liquid-interactive,
  .liquid-interactive > svg,
  .liquid-menu > *,
  .liquid-button > svg,
  .liquid-lens,
  [data-liquid-covered] {
    transition: none !important;
    animation: none !important;
  }
  .liquid-interactive {
    translate: none;
    scale: none;
  }
  .liquid-tabs {
    scale: none;
  }
  .liquid-menu[data-state="open"] {
    opacity: 1;
  }
}
@media (forced-colors: active) {
  .liquid-surface {
    border: 1px solid ButtonText;
  }
  .liquid-lens {
    background: Highlight;
    box-shadow: none;
  }
  .liquid-lens > .liquid-lens-optics {
    color: HighlightText;
  }
}
/* Liquid notifications. Keep Sonner's transform for stacking and swipe gestures. */
.liquid-toaster [data-sonner-toast].liquid-toast {
  position: absolute;
  width: var(--width);
  padding: 18px 44px 18px 18px;
  gap: 12px;
  border-radius: 28px;
  border: 1px solid rgb(255 255 255 / 0.8);
  color: var(--liquid-ink);
  background:
    linear-gradient(135deg, rgb(255 255 255 / 0.18), transparent 60%),
    rgb(var(--liquid-fill) / max(var(--liquid-tint), 0.72));
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.8);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.8);
  box-shadow:
    inset 0 1px 1px rgb(255 255 255 / 0.95),
    inset 0 -1px 1px rgb(255 255 255 / 0.3),
    0 12px 36px rgb(0 20 25 / 0.15),
    0 2px 8px rgb(0 20 25 / 0.05);
  scale: 0.45 0.7;
  transform-origin: top center;
  transition:
    transform 520ms cubic-bezier(0.2, 0.9, 0.25, 1.15),
    scale 520ms cubic-bezier(0.2, 0.9, 0.25, 1.15),
    opacity 180ms ease,
    height 380ms cubic-bezier(0.2, 0.9, 0.25, 1.1),
    border-radius 420ms ease,
    box-shadow 200ms ease;
}
.liquid-toaster [data-sonner-toast].liquid-toast[data-mounted="true"] {
  scale: 1;
}
.liquid-toaster [data-sonner-toast].liquid-toast[data-mounted="false"] {
  border-radius: 60px;
}
.liquid-toaster [data-sonner-toast].liquid-toast[data-removed="true"][data-swipe-out="false"] {
  scale: 0.55 0.75;
  border-radius: 60px;
  transition-duration: 180ms;
}
.liquid-toaster .liquid-toast [data-content] {
  gap: 4px;
  min-width: 0;
}
.liquid-toaster .liquid-toast [data-title] {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: -0.01em;
}
.liquid-toaster .liquid-toast [data-description] {
  font-size: 12px;
  line-height: 1.5;
  color: inherit;
  opacity: 0.65;
  overflow-wrap: anywhere;
}
.liquid-toaster .liquid-toast [data-icon] {
  align-self: center;
  margin: 0;
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  justify-content: center;
}
.liquid-toaster .liquid-toast [data-icon] svg {
  width: 20px;
  height: 20px;
}
.liquid-toaster .liquid-toast[data-type="success"] [data-icon] {
  color: #168451;
}
.liquid-toaster .liquid-toast[data-type="error"] [data-icon] {
  color: #cf3445;
}
.liquid-toaster .liquid-toast[data-type="warning"] [data-icon] {
  color: #ac6a0b;
}
.liquid-toaster .liquid-toast[data-type="info"] [data-icon] {
  color: #007aff;
}
.liquid-toaster .liquid-toast [data-content],
.liquid-toaster .liquid-toast [data-icon],
.liquid-toaster .liquid-toast [data-button] {
  opacity: 0;
  filter: blur(2px);
  transition:
    opacity 180ms ease 100ms,
    filter 260ms ease 80ms;
}
.liquid-toaster .liquid-toast[data-mounted="true"] [data-content],
.liquid-toaster .liquid-toast[data-mounted="true"] [data-icon],
.liquid-toaster .liquid-toast[data-mounted="true"] [data-button] {
  opacity: 1;
  filter: blur(0);
}
.liquid-toaster .liquid-toast[data-removed="true"] [data-content],
.liquid-toaster .liquid-toast[data-removed="true"] [data-icon] {
  opacity: 0;
  transition-delay: 0ms;
}
.liquid-toaster .liquid-toast[data-expanded="false"][data-front="false"] > * {
  opacity: 0;
}
.liquid-toaster [data-sonner-toast].liquid-toast [data-close-button] {
  left: auto;
  right: 12px;
